        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RECRUIT_VIEW_NO), LENGTH('RCTV' ) + 1)), 0) + 1, 6, '0')
    FROM RECRUIT_VIEW

	INSERT INTO RECRUIT_VIEW(
		RECRUIT_VIEW_NO
		, USER_ID
		, RECRUITMENT_NO
		, VIEW_AT
	)VALUES(
		#{recruitViewNo}
		, #{userId}
		, #{recruitmentNo}
		, SYSDATE
	)
